import{_ as a,o,c as t,a2 as l}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 42 话 Web Locks API：跨标签页互斥锁","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.42-web-locks.md","filePath":"comics/html/EP.42-web-locks.md","lastUpdated":1792579602000}'),r={name:"comics/html/EP.42-web-locks.md"};function c(i,e,s,d,n,h){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="漫画-·-第-42-话-web-locks-api-跨标签页互斥锁" tabindex="-1">漫画 · 第 42 话 Web Locks API：跨标签页互斥锁 <a class="header-anchor" href="#漫画-·-第-42-话-web-locks-api-跨标签页互斥锁" aria-label="Permalink to &quot;漫画 · 第 42 话 Web Locks API：跨标签页互斥锁&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/15-web-locks">docs/html/15-web-locks.md</a> ｜ 原画：<a href="./EP.42-web-locks.svg">EP.42-web-locks.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话苦主。用户开了三个标签同时编辑草稿，localStorage 被写成一锅粥——后写入的覆盖先写入的，数据丢失投诉不断。</li><li><strong>标签君</strong>：HTML5 结构师，掏出浏览器原生锁——<code>navigator.locks.request()</code> 按名称排队，独占锁写、共享锁读、回调结束自动释放，跨标签页/窗口/iframe 同源生效。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「多标签竞态」折磨：标签 A 写草稿、标签 B 同时写、Service Worker 也在抢，数据互相覆盖。标签君引入 Web Locks——<code>navigator.locks.request(&#39;draft&#39;, async () =&gt; { ... })</code> 一行搞定互斥，回调结束锁自动释放，页面崩溃浏览器也保证最终一致性。共享锁 <code>mode: &#39;shared&#39;</code> 让多标签并发读不阻塞；<code>ifAvailable: true</code> 拿不到立即返回不排队；<code>AbortSignal</code> 防止无限等待。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>同一站点三个标签同时打开，localStorage 写操作互相覆盖。IndexedDB 异步竞态、轮询同步顺序乱、Service Worker 也来抢——自己实现跨 tab 锁几乎不可能。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>navigator.locks.request(&#39;draft&#39;, async () =&gt; { ... })</code> 请求独占锁，同名锁同时只有一个持有者，回调结束自动释放。<code>mode: &#39;shared&#39;</code> 共享锁允许多个读并发；<code>ifAvailable: true</code> 非阻塞尝试；<code>signal</code> 支持 AbortSignal 超时。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：单标签写草稿（排队写入保一致）、读多写少缓存（shared 并发读 + exclusive 独占写）、非阻塞轮询（ifAvailable 拿不到就跳过）、AbortSignal 超时（防无限排队卡死）。记住边界：<strong>不要嵌套取同名锁</strong>，浏览器会抛异常防死锁。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>独占锁同时只一个持有者；共享锁并发读、排斥写——读多写少用 shared。</li><li>回调结束锁自动释放；页面崩溃浏览器也保证最终一致性。</li><li>不要嵌套取同名锁；锁名要语义化（&quot;user:123:draft&quot;）避免无意义排队。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 Web Locks 的回调必须是 async 函数？同步回调会有什么问题？</p><p><strong>答</strong>：锁的释放时机由回调返回的 Promise 决定——Promise resolve 时锁才释放。同步回调立即返回，锁在同步代码执行完就释放了，后续异步操作（如 <code>await fetch</code>）实际在无锁状态下运行，互斥失效。必须 <code>async</code> 并在回调内 <code>await</code> 所有异步操作。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>独占锁/共享锁对比 + ifAvailable 非阻塞 + 跨标签页竞态演示 + AbortSignal 超时：<a href="./../../examples/html/15-web-locks/index-01-web-locks.html">examples/html/15-web-locks/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 43 话《text-wrap 与 field-sizing》——<code>text-wrap: balance</code> 标题两行均分、<code>field-sizing: content</code> 输入框随内容自动伸缩、<code>interpolate-size</code> 解锁 auto 动画，排版细节原生搞定。</p>',22)])])}const m=a(r,[["render",c]]);export{u as __pageData,m as default};
